namespace sv_7dd9e752916e44938e845c859dade85c.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_7dd9e752916e44938e845c859dade85c.Components.Pages.Apply
@using sv_7dd9e752916e44938e845c859dade85c.Models

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       Company="@Entries[index].Company"
                       CompanyChanged="@(v => UpdateEntry(index, e => e with { Company = v }))"
                       Title="@Entries[index].Title"
                       TitleChanged="@(v => UpdateEntry(index, e => e with { Title = v }))"
                       StartDate="@Entries[index].StartDate"
                       StartDateChanged="@(v => UpdateEntry(index, e => e with { StartDate = v }))"
                       EndDate="@Entries[index].EndDate"
                       EndDateChanged="@(v => UpdateEntry(index, e => e with { EndDate = v }))"
                       IsCurrent="@(Entries[index].EndDate == null && !string.IsNullOrEmpty(Entries[index].Company))"
                       IsCurrentChanged="@(v => UpdateEntry(index, e => e with { EndDate = v ? null : DateTime.Today }))"
                       Description="@Entries[index].Description"
                       DescriptionChanged="@(v => UpdateEntry(index, e => e with { Description = v }))"
                       OnRemove="@(() => RemoveEntry(index))" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message" role="alert">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel>? Data { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<WorkEntryModel> Entries { get; set; } = new();
    private string? ErrorMessage { get; set; }

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Count > 0)
        {
            Entries = Data.Select(d => d with { }).ToList();
        }
        else if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntryModel());
        }
    }

    private void UpdateEntry(int index, Func<WorkEntryModel, WorkEntryModel> update)
    {
        Entries[index] = update(Entries[index]);
    }

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index) => Entries.RemoveAt(index);

    private async Task HandleNext()
    {
        ErrorMessage = null;
        if (Entries.Any(e => string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title)))
        {
            ErrorMessage = "Company and Job Title are required for each position.";
            return;
        }
        await OnNext.InvokeAsync(Entries);
    }
}

@* Mutable model used during editing *@
@code {
    public record WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; } = DateTime.Today;
        public string Description { get; set; } = "";
