@using sv_7dd9e752916e44938e845c859dade85c.Models

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       Company="@Entries[index].Company"
                       CompanyChanged="@(v => UpdateEntry(index, e => e with { Company = v }))"
                       Title="@Entries[index].Title"
                       TitleChanged="@(v => UpdateEntry(index, e => e with { Title = v }))"
                       StartDate="@Entries[index].StartDate"
                       StartDateChanged="@(v => UpdateEntry(index, e => e with { StartDate = v }))"
                       EndDate="@Entries[index].EndDate"
                       EndDateChanged="@(v => UpdateEntry(index, e => e with { EndDate = v }))"
                       IsCurrent="@(Entries[index].EndDate == null && !string.IsNullOrEmpty(Entries[index].Company))"
                       IsCurrentChanged="@(v => UpdateEntry(index, e => e with { EndDate = v ? null : DateTime.Today }))"
                       Description="@Entries[index].Description"
                       DescriptionChanged="@(v => UpdateEntry(index, e => e with { Description = v }))"
                       OnRemove="@(() => RemoveEntry(index))" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message" role="alert">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel>? Data { get; set; }
