@namespace sv_7dd9e752916e44938e845c859dade85c.Components.Pages.Apply
@using sv_7dd9e752916e44938e845c859dade85c.Models

<div class="step-content">
    <h2>References</h2>
    <p>Please provide 2-3 professional references.</p>

    @for (int i = 0; i < Refs.Count; i++)
    {
        var index = i;
        <ReferenceForm Index="index"
                       CanRemove="@(Refs.Count > 1)"
                       Name="@Refs[index].Name"
                       NameChanged="@(v => { Refs[index] = Refs[index] with { Name = v }; })"
                       Relationship="@Refs[index].Relationship"
                       RelationshipChanged="@(v => { Refs[index] = Refs[index] with { Relationship = v }; })"
                       Email="@Refs[index].Email"
                       EmailChanged="@(v => { Refs[index] = Refs[index] with { Email = v }; })"
                       Phone="@Refs[index].Phone"
                       PhoneChanged="@(v => { Refs[index] = Refs[index] with { Phone = v }; })"
                       OnRemove="@(() => Refs.RemoveAt(index))" />
    }

    @if (Refs.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddRef">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message" role="alert">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel>? Data { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<ReferenceModel> Refs { get; set; } = new();
    private string? ErrorMessage { get; set; }

    protected override void OnParametersSet()
    {
        if (Data is not null && Data.Count > 0)
        {
            Refs = Data.Select(r => r with { }).ToList();
        }
        else if (Refs.Count == 0)
        {
            Refs.Add(new ReferenceModel());
            Refs.Add(new ReferenceModel());
        }
    }

    private void AddRef() => Refs.Add(new ReferenceModel());

    private async Task HandleNext()
    {
        ErrorMessage = null;
        if (Refs.Any(r => string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
            || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone)))
        {
            ErrorMessage = "All fields are required for each reference.";
            return;
        }
        await OnNext.InvokeAsync(Refs);
    }

    public record ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

