@namespace sv_7dd9e752916e44938e845c859dade85c.Components.Pages.Apply
@using sv_7dd9e752916e44938e845c859dade85c.Models

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (Submitted)
    {
        <div class="confirmation" role="status">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <h3>Personal Information <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button></h3>
            <dl>
                <dt>Name</dt><dd>@Personal?.FullName</dd>
                <dt>Email</dt><dd>@Personal?.Email</dd>
                <dt>Phone</dt><dd>@Personal?.Phone</dd>
                <dt>Address</dt><dd>@Personal?.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <h3>Work History <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button></h3>
            @if (WorkEntries is not null)
            {
                @foreach (var entry in WorkEntries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at @entry.Company
                        <br />
                        <small>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <h3>References <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button></h3>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="review-entry">
                        <strong>@r.Name</strong> (@r.Relationship)
                        <br />@r.Email &bull; @r.Phone
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <h3>Cover Letter <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button></h3>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="error-message" role="alert">@ErrorMessage</div>
        }

        <div class="step-actions">
            <button class="btn-outline" @onclick="OnBack">Back</button>
            <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public List<WorkEntry>? WorkEntries { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEditSection { get; set; }
    [Parameter, EditorRequired] public Func<Task<int>> OnSubmit { get; set; } = default!;

    private bool IsSubmitting { get; set; }
    private bool Submitted { get; set; }
    private int ApplicationId { get; set; }
    private string? ErrorMessage { get; set; }

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;
        try
        {
            ApplicationId = await OnSubmit();
            Submitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

