+
+.review-section dt {
+    font-weight: 500;
+    color: #666;
+}
+
+.review-section dd {
+    margin: 0;
+}
+
+.review-entry {
+    margin-bottom: 0.75rem;
+    padding: 0.5rem;
+    background: #fafafa;
+    border-radius: 4px;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #fafafa;
+    padding: 1rem;
+    border-radius: 4px;
+    max-height: 200px;
+    overflow-y: auto;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.confirmation h3 {
+    color: #34a853;
+    font-size: 1.5rem;
+}
